
%% MATH 155 - Homework 4, Problem 1
% Salt-and-Pepper Noise Removal
% Norah Lynch
%
% Compare a 3x3 median filter with a
% 3x3 arithmetic averaging filter.
%
% Uses standard MATLAB operations.

clear; clc; close all;
rng(1); % Reproducible random noise

%% Select input image
I = imread('HW4Q1_original_image.jpg');

%% Convert to grayscale
if size(I, 3) == 3
    I = 0.2989 * double(I(:,:,1)) + ...
        0.5870 * double(I(:,:,2)) + ...
        0.1140 * double(I(:,:,3));
end

I = double(I);

%% Normalize input to [0,1]
I = I - min(I(:));
if max(I(:)) > 0
    I = I / max(I(:));
end

[M, N] = size(I);

%% Generate salt-and-pepper noise
% P(pepper) = 0.025
% P(original) = 0.95
% P(salt) = 0.025

noise = rand(M, N);

Inoisy = I;

Inoisy(noise < 0.025) = 0;
Inoisy(noise > 0.975) = 1;

%% Create padded image
% Replicated boundary pixels

Ipad = zeros(M+2, N+2);
Ipad(2:M+1, 2:N+1) = Inoisy;

Ipad(1, 2:N+1) = Inoisy(1,:);
Ipad(M+2, 2:N+1) = Inoisy(M,:);

Ipad(2:M+1, 1) = Inoisy(:,1);
Ipad(2:M+1, N+2) = Inoisy(:,N);

Ipad(1,1) = Inoisy(1,1);
Ipad(1,N+2) = Inoisy(1,N);
Ipad(M+2,1) = Inoisy(M,1);
Ipad(M+2,N+2) = Inoisy(M,N);

%% Initialize filtered images
Imedian = zeros(M,N);
Iaverage = zeros(M,N);

%% Apply 3x3 median and averaging filters
for i = 1:M
    for j = 1:N

        window = Ipad(i:i+2, j:j+2);

        % Median filter
        Imedian(i,j) = median(window(:));

        % Arithmetic averaging filter
        Iaverage(i,j) = mean(window(:));

    end
end

%% Display results
figure('Name', 'Salt and Pepper Noise Removal', ... %[output:6d9465c5]
       'Position', [100 100 1000 750]); %[output:6d9465c5]

subplot(2,2,1); %[output:6d9465c5]
imagesc(I, [0 1]); %[output:6d9465c5]
axis image off; %[output:6d9465c5]
colormap gray; %[output:6d9465c5]
title('Original Image'); %[output:6d9465c5]

subplot(2,2,2); %[output:6d9465c5]
imagesc(Inoisy, [0 1]); %[output:6d9465c5]
axis image off; %[output:6d9465c5]
title('Noisy Image'); %[output:6d9465c5]

subplot(2,2,3); %[output:6d9465c5]
imagesc(Imedian, [0 1]); %[output:6d9465c5]
axis image off; %[output:6d9465c5]
title('3x3 Median Filter'); %[output:6d9465c5]

subplot(2,2,4); %[output:6d9465c5]
imagesc(Iaverage, [0 1]); %[output:6d9465c5]
axis image off; %[output:6d9465c5]
title('3x3 Averaging Filter'); %[output:6d9465c5]

%% Save outputs
imwrite(Inoisy, 'HW4_P1_noisy.png');

imwrite(Imedian, 'HW4_P1_median.png');

imwrite(Iaverage, 'HW4_P1_averaging.png');

exportgraphics(gcf, ... %[output:group:2a46db07] %[output:6d9465c5]
    'HW4_P1_comparison.png'); %[output:group:2a46db07] %[output:6d9465c5]

%% Calculate mean squared errors
MSE_noisy = mean((I(:)-Inoisy(:)).^2);
MSE_median = mean((I(:)-Imedian(:)).^2);
MSE_average = mean((I(:)-Iaverage(:)).^2);

fprintf('\nMATH 155 - Homework 4, Problem 1\n'); %[output:2f651f5f]
fprintf('MSE before filtering: %.6f\n', MSE_noisy); %[output:3ede4c81]
fprintf('MSE after median filter: %.6f\n', MSE_median); %[output:755521f2]
fprintf('MSE after averaging filter: %.6f\n', MSE_average); %[output:6d582e10]

disp('All output images saved.'); %[output:65b49497]


